package com.muzamil.propertyreturnfiler;
import android.app.*;import android.content.*;import android.os.Build;
public class ReminderReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String ch="fbr";if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(ch,"FBR Reminders",NotificationManager.IMPORTANCE_HIGH));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("FBR Reminder").setContentText("Client property return reminder due hai.").setAutoCancel(true);n.notify((int)(System.currentTimeMillis()%99999),b.build());}}
